components.style:
/* Button */
.portal-button {
  --_bg: var(--portal-button-background, var(--_primary));
  /* --_state is the background of the current state; the derived text colour
     follows it, so hover and pressed keep legible text. */
  --_state: var(--_bg);
  --_fg: var(--portal-button-color, var(--portal-primary-content, oklch(from var(--_state) clamp(0, (0.62 - l) * 1000, 1) 0 0)));
  --_border: transparent;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: calc(var(--_s)*2);
  min-block-size: calc(var(--_s)*10);
  padding-block: calc(var(--_s)*2);
  padding-inline: calc(var(--_s)*4);
  border: 1px solid var(--_border);
  border-radius: var(--portal-radius);
  background: var(--_state);
  color: var(--_fg);
  box-shadow: var(--portal-shadow-sm);
  font: inherit;
  font-size: .875rem;
  font-weight: var(--_portal-weight-medium);
  line-height: 1.25rem;
  text-align: center;
  text-decoration: none;
  cursor: pointer;
  user-select: none;
  transition-property: background-color, border-color, color, box-shadow, opacity;
  transition-duration: var(--portal-motion);
  transition-timing-function: ease-out;
}
/* Hover and pressed move the background's OKLCH lightness toward mid-lightness,
   so a near-black or near-white brand still visibly responds. */
.portal-button:hover:not(:disabled) { --_state: oklch(from var(--_bg) calc(l + (0.5 - l) * 0.16) c h); }
.portal-button:active:not(:disabled) { --_state: oklch(from var(--_bg) calc(l + (0.5 - l) * 0.28) c h); box-shadow: none; }
.portal-button[data-variant="secondary"] {
  --_bg: var(--portal-secondary);
  --_fg: var(--portal-secondary-content);
  --_border: var(--_hairline);
}
.portal-button[data-variant="ghost"] {
  --_bg: transparent;
  --_fg: var(--portal-text);
  box-shadow: none;
}
.portal-button[data-variant="ghost"]:hover:not(:disabled) { background: var(--_tint); }
.portal-button[data-variant="ghost"]:active:not(:disabled) { background: color-mix(in oklab, var(--_primary) 18%, var(--portal-surface)); }
.portal-button[data-variant="danger"] {
  --_bg: var(--portal-danger);
  --_fg: var(--portal-danger-content);
}
.portal-button[data-size="sm"] {
  min-block-size: calc(var(--_s)*8);
  padding-block: calc(var(--_s)*1);
  padding-inline: calc(var(--_s)*3);
  font-size: .8125rem;
}
.portal-button[data-size="lg"] {
  min-block-size: calc(var(--_s)*11);
  padding-inline: calc(var(--_s)*6);
  font-size: 1rem;
}
/* Disabled is muted, not faded: its text stays readable on every preset. */
.portal-button:disabled { --_state: var(--portal-surface-muted); border-color: var(--_hairline); color: var(--portal-text-muted); box-shadow: none; cursor: not-allowed; }
/* Studio buttons are pills. :where keeps the preset as specific as the button
   itself, so an author rule still wins. */
.portal-button:where(.portal-theme[data-preset="studio"] *) { border-radius: 999px; }

/* Browsers without CSS relative colour (oklch(from …)) keep a usable button:
   text is --portal-primary-content or white, and hover and pressed mix the
   background toward the canvas instead of shifting its lightness. */
@supports not (color: oklch(from red l c h)) {
  /* The canvas sits opposite the brand in every preset, so the label takes it. Hover lightens a little towards the canvas; pressed deepens towards the text, which only adds contrast. */
  .portal-button { --_fg: var(--portal-button-color, var(--portal-primary-content, var(--portal-canvas))); }
  .portal-button:hover:not(:disabled) { --_state: color-mix(in oklab, var(--_bg) 88%, var(--portal-canvas)); }
  .portal-button:active:not(:disabled) { --_state: color-mix(in oklab, var(--_bg) 76%, var(--portal-text)); }
}
@media (forced-colors: active) {
  .portal-button { border: 1px solid ButtonText; }
}

.portal-link[data-variant="button"] {
  --_bg: var(--portal-button-background, var(--_primary));
  /* --_state is the background of the current state; the derived text colour
     follows it, so hover and pressed keep legible text. */
  --_state: var(--_bg);
  --_fg: var(--portal-button-color, var(--portal-primary-content, oklch(from var(--_state) clamp(0, (0.62 - l) * 1000, 1) 0 0)));
  --_border: transparent;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: calc(var(--_s)*2);
  min-block-size: calc(var(--_s)*10);
  padding-block: calc(var(--_s)*2);
  padding-inline: calc(var(--_s)*4);
  border: 1px solid var(--_border);
  border-radius: var(--portal-radius);
  background: var(--_state);
  color: var(--_fg);
  box-shadow: var(--portal-shadow-sm);
  font: inherit;
  font-size: .875rem;
  font-weight: var(--_portal-weight-medium);
  line-height: 1.25rem;
  text-align: center;
  text-decoration: none;
  cursor: pointer;
  user-select: none;
  transition-property: background-color, border-color, color, box-shadow, opacity;
  transition-duration: var(--portal-motion);
  transition-timing-function: ease-out;
}
.portal-link[data-variant="button"]:hover { --_state: oklch(from var(--_bg) calc(l + (0.5 - l) * 0.16) c h); }
.portal-link[data-variant="button"]:active { --_state: oklch(from var(--_bg) calc(l + (0.5 - l) * 0.28) c h); box-shadow: none; }
.portal-link[data-variant="button"]:where(.portal-theme[data-preset="studio"] *) { border-radius: 999px; }

/* Link: quiet text with a brand underline that firms up on hover. */
.portal-link {
  color: var(--portal-text);
  font-weight: var(--_portal-weight-medium);
  text-decoration-line: underline;
  text-decoration-thickness: 1px;
  text-decoration-color: color-mix(in oklab, var(--_primary) 55%, transparent);
  text-underline-offset: .25em;
  transition-property: text-decoration-color, color;
  transition-duration: var(--portal-motion);
}
.portal-link:hover { text-decoration-color: var(--_primary); }

/* Browsers without CSS relative colour (oklch(from …)) keep a usable button:
   text is --portal-primary-content or white, and hover and pressed mix the
   background toward the canvas instead of shifting its lightness. */
@supports not (color: oklch(from red l c h)) {
  .portal-link[data-variant="button"] { --_fg: var(--portal-button-color, var(--portal-primary-content, var(--portal-canvas))); }
  .portal-link[data-variant="button"]:hover { --_state: color-mix(in oklab, var(--_bg) 88%, var(--portal-canvas)); }
  .portal-link[data-variant="button"]:active { --_state: color-mix(in oklab, var(--_bg) 76%, var(--portal-text)); }
}

/* Badge: a quiet pill; status variants add a coloured dot and faint tint. */
.portal-badge {
  --_dot: var(--portal-text-muted);
  display: inline-flex;
  align-items: center;
  gap: .375rem;
  padding-block: .0625rem;
  padding-inline: .5rem;
  border: 1px solid var(--_hairline);
  border-radius: 999px;
  background: var(--portal-surface);
  color: var(--portal-text);
  font-size: .75rem;
  font-weight: var(--_portal-weight-medium);
  line-height: 1.25rem;
  white-space: nowrap;
}
.portal-badge[data-dot]::before {
  content: "";
  flex: none;
  inline-size: .375rem;
  block-size: .375rem;
  border-radius: 50%;
  background: var(--_dot);
}
.portal-badge[data-variant="primary"] { --_dot: var(--_primary); background: color-mix(in oklab, var(--_primary) 6%, var(--portal-surface)); }
.portal-badge[data-variant="success"] { --_dot: var(--portal-success); background: color-mix(in oklab, var(--portal-success) 6%, var(--portal-surface)); }
.portal-badge[data-variant="warning"] { --_dot: var(--portal-warning); background: color-mix(in oklab, var(--portal-warning) 6%, var(--portal-surface)); }
.portal-badge[data-variant="danger"] { --_dot: var(--portal-danger); background: color-mix(in oklab, var(--portal-danger) 6%, var(--portal-surface)); }
@media (forced-colors: active) {
  .portal-badge { border: 1px solid ButtonText; }
  .portal-badge::before { background: CanvasText; }
}

/* Card */
.portal-card {
  background: var(--portal-surface);
  color: var(--portal-text);
  border: 1px solid var(--_hairline);
  border-radius: calc(var(--portal-radius)*1.5);
  box-shadow: var(--portal-card-shadow, var(--portal-shadow-sm));
  overflow: clip;
}
.portal-card__header, .portal-card__body, .portal-card__footer { padding: calc(var(--_s)*6); }
.portal-card__header { border-block-end: 1px solid var(--_hairline); }
.portal-card__header + .portal-card__body { padding-block-start: calc(var(--_s)*5); }
.portal-card__footer {
  border-block-start: 1px solid var(--_hairline);
  background: var(--_subtle);
  padding-block: calc(var(--_s)*4);
}
.portal-card__header :is(h2, h3) { font-size: 1.125rem; }
.portal-card__header > :first-child, .portal-card__body > :first-child, .portal-card__footer > :first-child { margin-block-start: 0; }
.portal-card__header > :last-child, .portal-card__body > :last-child, .portal-card__footer > :last-child { margin-block-end: 0; }
@media (forced-colors: active) {
  .portal-card { border: 1px solid ButtonText; }
}

/* Alert */
.portal-alert {
  --_tone: var(--portal-info);
  padding-block: calc(var(--_s)*4);
  padding-inline: calc(var(--_s)*4);
  border: 1px solid var(--_hairline);
  border-inline-start: 3px solid var(--_tone);
  border-radius: var(--portal-radius);
  background: color-mix(in oklab, var(--_tone) 5%, var(--portal-surface));
  color: var(--portal-text);
  font-size: .9375rem;
}
.portal-alert[data-variant="warning"] { --_tone: var(--portal-warning); }
.portal-alert[data-variant="danger"] { --_tone: var(--portal-danger); }
.portal-alert[data-variant="success"] { --_tone: var(--portal-success); }
.portal-alert__title { font-weight: var(--_portal-weight-strong); margin-block-end: calc(var(--_s)*1); }
.portal-alert p { margin-block: calc(var(--_s)*1); }
.portal-alert > div:last-child:not(:first-child) { margin-block-start: calc(var(--_s)*3); }
@media (forced-colors: active) {
  .portal-alert { border: 1px solid ButtonText; }
}

/* Layout primitives */
.portal-container {
  inline-size: 100%;
  max-inline-size: var(--portal-content-width);
  margin-inline: auto;
  padding-inline: calc(var(--_s)*4);
}
.portal-container[data-width="reading"] { max-inline-size: var(--portal-reading-width); }
.portal-container[data-width="full"] { max-inline-size: none; }

.portal-stack { display: flex; flex-direction: column; gap: calc(var(--_s)*4); align-items: stretch; }
.portal-stack[data-direction="horizontal"] { flex-direction: row; flex-wrap: wrap; }
.portal-stack[data-align="start"] { align-items: flex-start; }
.portal-stack[data-align="center"] { align-items: center; }
.portal-stack[data-align="end"] { align-items: flex-end; }
.portal-stack[data-gap="sm"] { gap: calc(var(--_s)*2); }
.portal-stack[data-gap="lg"] { gap: calc(var(--_s)*6); }

.portal-grid { display: grid; gap: calc(var(--_s)*4); grid-template-columns: repeat(3, minmax(0, 1fr)); }
.portal-grid[data-columns="2"] { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.portal-grid[data-columns="4"] { grid-template-columns: repeat(4, minmax(0, 1fr)); }
.portal-grid[data-gap="sm"] { gap: calc(var(--_s)*2); }
.portal-grid[data-gap="lg"] { gap: calc(var(--_s)*6); }
@media (max-width: 40rem) { .portal-grid { grid-template-columns: 1fr !important; }
}

/* Fields */
.portal-field { display: grid; gap: calc(var(--_s)*2); }
.portal-field__description { color: var(--portal-text-muted); font-size: .875rem; margin: 0; }

.portal-input {
  inline-size: 100%;
  min-block-size: calc(var(--_s)*10);
  padding-block: calc(var(--_s)*2);
  padding-inline: calc(var(--_s)*3);
  color: var(--portal-input-color, var(--portal-text));
  background: var(--portal-input-background, var(--portal-surface));
  border: 1px solid var(--portal-border);
  border-radius: var(--portal-radius);
  box-shadow: var(--portal-shadow-sm);
  font: inherit;
  font-size: 1rem;
  line-height: 1.5rem;
  transition-property: border-color, box-shadow, background-color;
  transition-duration: var(--portal-motion);
  transition-timing-function: ease-out;
}
.portal-input::placeholder { color: var(--portal-text-muted); opacity: 1; }
.portal-input:hover:not(:disabled, :focus-visible) { border-color: color-mix(in oklab, var(--portal-border) 70%, var(--portal-text)); }
.portal-input:focus-visible {
  /* Transparent outline keeps a visible indicator in forced-colours mode. */
  outline: 2px solid transparent;
  outline-offset: 2px;
  border-color: var(--_focus-solid);
  box-shadow: 0 0 0 3px var(--_ring);
}
.portal-input[aria-invalid="true"] {
  --_focus: var(--portal-danger);
  border-color: var(--portal-danger);
}
.portal-input:disabled {
  background: var(--portal-surface-muted);
  color: var(--portal-text-muted);
  box-shadow: none;
  cursor: not-allowed;
}
.portal-input:read-only:not(:disabled) { background: var(--_subtle); }

.portal-textarea {
  inline-size: 100%;
  min-block-size: calc(var(--_s)*10);
  padding-block: calc(var(--_s)*2);
  padding-inline: calc(var(--_s)*3);
  color: var(--portal-input-color, var(--portal-text));
  background: var(--portal-input-background, var(--portal-surface));
  border: 1px solid var(--portal-border);
  border-radius: var(--portal-radius);
  box-shadow: var(--portal-shadow-sm);
  font: inherit;
  font-size: 1rem;
  line-height: 1.5rem;
  transition-property: border-color, box-shadow, background-color;
  transition-duration: var(--portal-motion);
  transition-timing-function: ease-out;
}
.portal-textarea { resize: vertical; min-block-size: calc(var(--_s)*20); }
.portal-textarea::placeholder { color: var(--portal-text-muted); opacity: 1; }
.portal-textarea:hover:not(:disabled, :focus-visible) { border-color: color-mix(in oklab, var(--portal-border) 70%, var(--portal-text)); }
.portal-textarea:focus-visible {
  /* Transparent outline keeps a visible indicator in forced-colours mode. */
  outline: 2px solid transparent;
  outline-offset: 2px;
  border-color: var(--_focus-solid);
  box-shadow: 0 0 0 3px var(--_ring);
}
.portal-textarea[aria-invalid="true"] {
  --_focus: var(--portal-danger);
  border-color: var(--portal-danger);
}
.portal-textarea:disabled {
  background: var(--portal-surface-muted);
  color: var(--portal-text-muted);
  box-shadow: none;
  cursor: not-allowed;
}
.portal-textarea:read-only:not(:disabled) { background: var(--_subtle); }

.portal-select {
  inline-size: 100%;
  min-block-size: calc(var(--_s)*10);
  padding-block: calc(var(--_s)*2);
  padding-inline: calc(var(--_s)*3);
  color: var(--portal-input-color, var(--portal-text));
  background: var(--portal-input-background, var(--portal-surface));
  border: 1px solid var(--portal-border);
  border-radius: var(--portal-radius);
  box-shadow: var(--portal-shadow-sm);
  font: inherit;
  font-size: 1rem;
  line-height: 1.5rem;
  transition-property: border-color, box-shadow, background-color;
  transition-duration: var(--portal-motion);
  transition-timing-function: ease-out;
}
.portal-select:hover:not(:disabled, :focus-visible) { border-color: color-mix(in oklab, var(--portal-border) 70%, var(--portal-text)); }
.portal-select:focus-visible {
  /* Transparent outline keeps a visible indicator in forced-colours mode. */
  outline: 2px solid transparent;
  outline-offset: 2px;
  border-color: var(--_focus-solid);
  box-shadow: 0 0 0 3px var(--_ring);
}
.portal-select[aria-invalid="true"] {
  --_focus: var(--portal-danger);
  border-color: var(--portal-danger);
}
.portal-select:disabled {
  background: var(--portal-surface-muted);
  color: var(--portal-text-muted);
  box-shadow: none;
  cursor: not-allowed;
}

/* Error summary */
.portal-error-summary {
  padding: calc(var(--_s)*5);
  border: 1px solid var(--portal-danger);
  border-inline-start-width: 3px;
  border-radius: var(--portal-radius);
  background: color-mix(in oklab, var(--portal-danger) 5%, var(--portal-surface));
  color: var(--portal-text);
}
.portal-error-summary h2 { margin-block-start: 0; margin-block-end: calc(var(--_s)*2); font-size: 1rem; letter-spacing: normal; }
.portal-error-summary ul { margin: 0; padding-inline-start: 1.25rem; }
.portal-error-summary a { color: color-mix(in oklab, var(--portal-danger) 80%, var(--portal-text)); font-weight: var(--_portal-weight-medium); text-underline-offset: .2em; }
.portal-error-summary a:hover { text-decoration-thickness: 2px; }

/* Disclosure */
.portal-disclosure {
  border: 1px solid var(--_hairline);
  border-radius: var(--portal-radius);
  background: var(--portal-surface);
}
.portal-disclosure summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: calc(var(--_s)*3);
  padding-block: calc(var(--_s)*3);
  padding-inline: calc(var(--_s)*4);
  border-radius: inherit;
  font-weight: var(--_portal-weight-medium);
  list-style: none;
  cursor: pointer;
  transition: background-color var(--portal-motion);
}
.portal-disclosure summary::-webkit-details-marker { display: none; }
.portal-disclosure summary::after {
  content: "";
  flex: none;
  inline-size: .5rem;
  block-size: .5rem;
  margin-block-start: -.25rem;
  border-block-end: 1.5px solid var(--portal-text-muted);
  border-inline-end: 1.5px solid var(--portal-text-muted);
  transform: rotate(45deg);
  transition: transform var(--portal-motion);
}
.portal-disclosure[open] > summary::after { transform: rotate(225deg); margin-block-start: .25rem; }
.portal-disclosure summary:dir(rtl)::after { transform: rotate(-45deg); }
.portal-disclosure[open] > summary:dir(rtl)::after { transform: rotate(-225deg); }
.portal-disclosure summary:hover { background: color-mix(in oklab, var(--portal-surface-muted) 60%, var(--portal-surface)); }
.portal-disclosure[open] > summary { border-end-start-radius: 0; border-end-end-radius: 0; }
.portal-disclosure__body {
  padding-inline: calc(var(--_s)*4);
  padding-block-end: calc(var(--_s)*4);
  color: var(--portal-text);
}
.portal-disclosure__body > :first-child { margin-block-start: 0; }
.portal-disclosure__body > :last-child { margin-block-end: 0; }

/* Breadcrumbs and pagination */
.portal-breadcrumbs ol {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: calc(var(--_s)*2);
  list-style: none;
  margin: 0;
  padding: 0;
}
.portal-breadcrumbs { font-size: .875rem; color: var(--portal-text-muted); }
.portal-breadcrumbs li + li::before { content: "/"; margin-inline-end: calc(var(--_s)*2); color: color-mix(in oklab, var(--portal-text-muted) 70%, transparent); }
.portal-breadcrumbs a {
  color: var(--portal-text-muted);
  text-decoration: none;
  border-radius: calc(var(--portal-radius)*.6);
  transition: color var(--portal-motion);
}
.portal-breadcrumbs a:hover { color: var(--portal-text); text-decoration: underline; text-underline-offset: .2em; }
.portal-breadcrumbs [aria-current="page"] { color: var(--portal-text); font-weight: var(--_portal-weight-medium); }

.portal-pagination ul {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: calc(var(--_s)*2);
  list-style: none;
  margin: 0;
  padding: 0;
}
.portal-pagination { font-size: .875rem; }
.portal-pagination a, .portal-pagination span {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-inline-size: calc(var(--_s)*10);
  min-block-size: calc(var(--_s)*10);
  padding-inline: calc(var(--_s)*3);
  border: 1px solid transparent;
  border-radius: var(--portal-radius);
  color: var(--portal-text);
  font-weight: var(--_portal-weight-medium);
  text-decoration: none;
  transition-property: background-color, border-color;
  transition-duration: var(--portal-motion);
}
.portal-pagination a:hover { background: var(--_tint); }
.portal-pagination [aria-current="page"] { border-color: var(--_hairline); background: var(--portal-surface); box-shadow: var(--portal-shadow-sm); }
.portal-pagination [aria-current="page"]:hover { background: var(--portal-surface); border-color: var(--portal-border); }
.portal-pagination [aria-disabled="true"] { color: var(--portal-text-muted); cursor: not-allowed; }
@media (forced-colors: active) {
  .portal-pagination [aria-current="page"] { border: 1px solid ButtonText; }
}

/* Empty state */
.portal-empty-state {
  display: grid;
  justify-items: center;
  gap: calc(var(--_s)*2);
  text-align: center;
  padding-block: calc(var(--_s)*10);
  padding-inline: calc(var(--_s)*6);
  border: 1px dashed var(--_hairline);
  border-radius: calc(var(--portal-radius)*1.5);
  color: var(--portal-text-muted);
}
.portal-empty-state h2 { margin: 0; font-size: 1.125rem; color: var(--portal-text); }
.portal-empty-state > div { max-inline-size: var(--portal-reading-width); }
.portal-empty-state > div > :first-child { margin-block-start: 0; }
.portal-empty-state > div > :last-child { margin-block-end: 0; }
.portal-empty-state > div:last-child:not(:nth-child(2)) { margin-block-start: calc(var(--_s)*3); }

/* Skeleton */
.portal-skeleton {
  display: block;
  block-size: 1rem;
  inline-size: 100%;
  margin-block: calc(var(--_s)*2);
