  .portal-site-header__brand { flex: 1 1 8rem; }
  .portal-site-header__nav { order: 1; flex-basis: 100%; margin-inline: calc(var(--_s)*-2.5); }
}

/* Nav link: quiet muted text; hover gains the text colour and a soft surface. */
.portal-nav-link {
  display: inline-flex;
  align-items: center;
  gap: calc(var(--_s)*1.5);
  min-block-size: calc(var(--_s)*9);
