  .portal-tabs__tab[aria-selected="true"] { border: 1px solid ButtonText; }
}

.portal-tab-panel[role] > .portal-tab-panel__title { position: absolute; inline-size: 1px; block-size: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.portal-tab-panel > :nth-child(2) { margin-block-start: 0; }
.portal-tab-panel > :last-child { margin-block-end: 0; }
.portal-tab-panel__title { margin-block: 0 calc(var(--_s)*3); font-size: 1.125rem; }
.portal-tab-panel:not([role]) + .portal-tab-panel { margin-block-start: calc(var(--_s)*8); }

/* Description list: stacked label-over-value cells, or inline rows. */
.portal-description-list { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(100%, 12rem), 1fr)); gap: calc(var(--_s)*4) calc(var(--_s)*6); margin: 0; }
.portal-description-list[data-layout="inline"] { display: block; }
.portal-description-list[data-layout="inline"] .portal-description-item { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 0 calc(var(--_s)*4); padding-block: calc(var(--_s)*1.5); font-size: .9375rem; }
.portal-description-list[data-layout="inline"] dt { font-size: inherit; }
.portal-description-list[data-layout="inline"] dd { margin: 0; font-variant-numeric: tabular-nums; }

.portal-description-item { min-inline-size: 0; }
.portal-description-item dt { color: var(--portal-text-muted); font-size: .8125rem; }
.portal-description-item dd { margin: .125rem 0 0; overflow-wrap: anywhere; }

.portal-timeline-step { position: relative; display: flex; gap: calc(var(--_s)*3); padding-block-end: calc(var(--_s)*5); }
.portal-timeline-step:last-child { padding-block-end: 0; }
.portal-timeline-step:not(:last-child)::before { content: ""; position: absolute; inset-block: 1.625rem .25rem; inset-inline-start: calc(.625rem - 1px); inline-size: 2px; border-radius: 1px; background: var(--_hairline); }
.portal-timeline-step[data-state="done"]::before { background: var(--_primary); }
.portal-timeline-step__marker { display: grid; flex: none; place-items: center; inline-size: 1.25rem; block-size: 1.25rem; margin-block-start: .125rem; border: 1.5px solid var(--portal-border); border-radius: 50%; background: var(--portal-surface); font-size: .75rem; }
.portal-timeline-step__marker > *, .portal-timeline-step__marker::after { grid-area: 1 / 1; }
.portal-timeline-step:not([data-state="done"]) .portal-icon { display: none; }
.portal-timeline-step[data-state="done"] .portal-timeline-step__marker { border-color: var(--_primary); background: var(--_primary); color: var(--portal-primary-content, oklch(from var(--_primary) clamp(0, (0.62 - l) * 1000, 1) 0 0)); }
.portal-timeline-step[data-state="current"] .portal-timeline-step__marker { border-color: var(--_primary); box-shadow: 0 0 0 3px var(--_ring); }
.portal-timeline-step[data-state="current"] .portal-timeline-step__marker::after { content: ""; inline-size: .5rem; block-size: .5rem; border-radius: 50%; background: var(--_primary); }
.portal-timeline-step__body { flex: 1; min-inline-size: 0; }
.portal-timeline-step__head { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: space-between; gap: 0 calc(var(--_s)*3); margin: 0; overflow-wrap: anywhere; }
.portal-timeline-step__title { font-weight: var(--_portal-weight-medium); }
.portal-timeline-step[data-state="upcoming"] .portal-timeline-step__title, .portal-timeline-step__time, .portal-timeline-step__detail { color: var(--portal-text-muted); font-size: .875rem; }
.portal-timeline-step[data-state="upcoming"] .portal-timeline-step__title { font-size: 1rem; }
.portal-timeline-step__detail { margin-block-start: .125rem; }

/* Browsers without CSS relative colour (oklch(from …)) keep a usable button:
   text is --portal-primary-content or white, and hover and pressed mix the
   background toward the canvas instead of shifting its lightness. */
@supports not (color: oklch(from red l c h)) {
  .portal-timeline-step[data-state="done"] .portal-timeline-step__marker { color: var(--portal-primary-content, var(--portal-canvas)); }
}

.portal-stat__label { color: var(--portal-text-muted); font-size: .875rem; }
.portal-stat { padding: calc(var(--_s)*5); }
.portal-stat p { margin: 0; overflow-wrap: anywhere; }
.portal-stat__value { margin-block: calc(var(--_s)*1) !important; font-family: var(--portal-font-heading); font-size: 1.75rem; font-weight: var(--_portal-weight-strong); letter-spacing: var(--_portal-heading-tracking); line-height: 1.15; font-variant-numeric: tabular-nums; }
.portal-stat__change { display: flex; align-items: center; gap: .25rem; font-size: .8125rem; font-weight: var(--_portal-weight-medium); }
.portal-stat__change[data-trend="up"] { color: color-mix(in oklab, var(--portal-success) 75%, var(--portal-text)); }
.portal-stat__change[data-trend="down"] { color: color-mix(in oklab, var(--portal-danger) 75%, var(--portal-text)); }
/* t:if is truthiness-only, so both arrows render and the trend picks one. */
.portal-stat__change[data-trend="flat"] [data-icon="arrow-up-right"], .portal-stat__change:not([data-trend="flat"]) [data-icon="arrow-right"] { display: none; }
.portal-stat__change[data-trend="down"] .portal-icon { scale: 1 -1; }

.portal-estimate__delivery { color: var(--portal-text-muted); font-size: .875rem; }
.portal-estimate__head { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: calc(var(--_s)*2); margin-block-end: calc(var(--_s)*3); }
.portal-estimate__head .portal-panel__title { margin: 0; }
.portal-estimate__delivery { display: flex; align-items: center; gap: calc(var(--_s)*2); margin: calc(var(--_s)*2) 0 0; }

.portal-file-item__meta { color: var(--portal-text-muted); font-size: .875rem; }
.portal-file-item + .portal-file-item { border-block-start: 1px solid var(--_hairline); }
.portal-file-item a { display: flex; align-items: center; gap: calc(var(--_s)*3); padding: calc(var(--_s)*3) calc(var(--_s)*4); color: var(--portal-text); text-decoration: none; }
.portal-file-item a:hover { background: var(--_subtle); }
.portal-file-item a:focus-visible { outline-offset: -2px; }
.portal-file-item .portal-icon { color: var(--portal-text-muted); }
.portal-file-item__text { display: grid; flex: 1; min-inline-size: 0; overflow-wrap: anywhere; }
.portal-file-item__name { font-size: .9375rem; font-weight: var(--_portal-weight-medium); }
.portal-file-item__meta { font-size: .8125rem; }
.portal-file-item__meta span + span::before { content: " · "; }

.portal-code-block__bar:not(:has(> :not([hidden]))) { display: none; }

/* Developer */
.portal-code-block { border: 1px solid var(--_hairline); border-radius: var(--portal-radius); background: var(--_subtle); }
.portal-code-block { overflow: clip; }
.portal-code-block__bar { display: flex; align-items: center; justify-content: space-between; gap: calc(var(--_s)*2); padding-block: calc(var(--_s)*1.5); padding-inline: calc(var(--_s)*4) calc(var(--_s)*2); border-block-end: 1px solid var(--_hairline); color: var(--portal-text-muted); font-size: .8125rem; }
.portal-code-block__language { font-weight: var(--_portal-weight-medium); }
.portal-code-block pre { margin: 0; padding: calc(var(--_s)*4); overflow-x: auto; font-size: .8125rem; line-height: 1.7; tab-size: 2; }
.portal-code-block pre:focus-visible { outline-offset: -2px; }
.portal-code-block pre code { font-size: inherit; }

.portal-endpoint__summary { color: var(--portal-text-muted); font-size: .875rem; }
.portal-endpoint { padding-block: calc(var(--_s)*6); }
.portal-endpoint + .portal-endpoint { border-block-start: 1px solid var(--_hairline); }
.portal-endpoint > :last-child { margin-block-end: 0; }
.portal-endpoint > :not(h3, p) { margin-block-start: calc(var(--_s)*4); }
.portal-endpoint__title { display: flex; flex-wrap: wrap; align-items: center; gap: calc(var(--_s)*2.5); margin: 0; font-size: 1rem; letter-spacing: normal; }
.portal-endpoint__title code { min-inline-size: 0; font-size: .9375rem; overflow-wrap: anywhere; }
.portal-endpoint__method {
  --_tone: var(--portal-info);
  padding: 0 .5rem;
  border-radius: calc(var(--portal-radius)*.75);
  background: color-mix(in oklab, var(--_tone) 14%, var(--portal-surface));
  color: color-mix(in oklab, var(--_tone) 70%, var(--portal-text));
  font-family: var(--portal-font-mono);
  font-size: .75rem;
  line-height: 1.5rem;
  letter-spacing: .04em;
}
.portal-endpoint[data-method="POST"] > * > .portal-endpoint__method { --_tone: var(--portal-success); }
.portal-endpoint:is([data-method="PUT"], [data-method="PATCH"]) > * > .portal-endpoint__method { --_tone: var(--portal-warning); }
.portal-endpoint[data-method="DELETE"] > * > .portal-endpoint__method { --_tone: var(--portal-danger); }
.portal-endpoint__summary { margin: calc(var(--_s)*2) 0 0; font-size: .9375rem; }

.portal-key-display__row { border: 1px solid var(--_hairline); border-radius: var(--portal-radius); background: var(--_subtle); }
.portal-key-display { display: grid; gap: calc(var(--_s)*2); }
.portal-key-display__row { display: flex; align-items: center; gap: calc(var(--_s)*2.5); min-block-size: calc(var(--_s)*10); padding: calc(var(--_s)*1); padding-inline-start: calc(var(--_s)*3); color: var(--portal-text-muted); }
.portal-key-display__masked { flex: 1; min-inline-size: 0; color: var(--portal-text); overflow-wrap: anywhere; }

/* General */
.portal-avatar { position: relative; display: inline-grid; flex: none; place-items: center; inline-size: 2.5rem; block-size: 2.5rem; overflow: clip; border-radius: 50%; background: color-mix(in oklab, var(--_primary) 14%, var(--portal-surface)); color: var(--portal-text); font-size: .875rem; font-weight: var(--_portal-weight-medium); }
.portal-avatar[data-size="sm"] { inline-size: 2rem; block-size: 2rem; font-size: .75rem; }
.portal-avatar[data-size="lg"] { inline-size: 3.5rem; block-size: 3.5rem; font-size: 1.125rem; }
.portal-avatar img { position: absolute; inset: 0; inline-size: 100%; block-size: 100%; object-fit: cover; }
